parameters.command:
cat > /tmp/celsius_plan.json << 'EOF'
{
  "ops": [
    {
      "op": "insert-between",
      "upstream": "getWeather",
      "downstream": "formatSummary",
      "id": "convertToCelsius",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "label": "Convert to Celsius",
      "inputs": {
        "script": "const tempF = $vars.getWeather.output.body.current.temperature_2m;\nconst tempC = Math.round((tempF - 32) * 5 / 9 * 10) / 10;\nreturn { temperatureF: tempF, temperatureC: tempC };"
      }
    },
    {
      "op": "set-input",
      "node": "formatSummary",
      "key": "script",
      "value": "const tempF = $vars.convertToCelsius.output.temperatureF;\nconst tempC = $vars.convertToCelsius.output.temperatureC;\nconst time = $vars.getWeather.output.body.current.time;\nreturn {\n  temperatureF: tempF,\n  temperatureC: tempC,\n  summary: 'Bellevue weather today: ' + tempF + 'F (' + tempC + 'C) at ' + time\n};"
    }
  ]
}
EOF
python3 /home/azureuser/projects/skills/tmp/skills/uipath-maestro-flow/scripts/flow_edit.py apply \
  --flow /work/output/artifacts/skill-flow-add-node/BellevueWeather/BellevueWeather/BellevueWeather.flow \
  --plan /tmp/celsius_plan.json

